function construct_gsn_endpoint_basis_h_hc_s0(lambda, m, nu, omega)
    lambda = ComplexF64(lambda)
    m = Float64(m)
    nu = Float64(nu)
    omega = ComplexF64(omega)
    m2 = m * m
    o2 = omega * omega
    s1 = sin(nu)
    c1 = sqrt((1 - s1) * (1 + s1))
    sn = s1
    c = c1
    cp2 = c * c
    cp3 = cp2 * c
    cp4 = cp3 * c
    cp5 = cp4 * c
    cp6 = cp5 * c
    cp7 = cp6 * c
    cp8 = cp7 * c
    cp9 = cp8 * c
    cp10 = cp9 * c
    u = s1 * s1 / (1 + c1)
    up2 = u * u
    up3 = up2 * u
    up4 = up3 * u
    coeffs = Vector{ComplexF64}(undef, LEN_GSN_ENDPOINT_h_hc_s0)
    _construct_gsn_endpoint_basis_h_hc_s0_block_1!(coeffs, cp2, cp3, u)
    _construct_gsn_endpoint_basis_h_hc_s0_block_2!(coeffs, cp2, cp3, cp4, u)
    _construct_gsn_endpoint_basis_h_hc_s0_block_3!(coeffs)
    _construct_gsn_endpoint_basis_h_hc_s0_block_4!(coeffs, lambda, m, omega, m2, o2, sn, cp2, cp3, cp4, cp5, cp6, cp7, cp8, u, up2, up3, up4)
    _construct_gsn_endpoint_basis_h_hc_s0_block_5!(coeffs, m, omega, m2, o2, sn, cp2, cp3, cp4, cp5, cp6, cp7, cp8, up3, up4)
    _construct_gsn_endpoint_basis_h_hc_s0_block_6!(coeffs, cp4, cp5, cp6, cp7, u, up2)
    return coeffs
end

